(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zl-sj-prepa-med-j4-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zl-sj-prepa-med-j4-ide\",\n \"titre\": \"Préparation D.E (J) · J4 Médecine IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 50,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J4 (IDE)\",\n     \"slug\": \"prepa-med-j4-ide\",\n     \"pages\": \"\",\n     \"count\": 50,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__0\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 : M. KOUAME Oi Kouamé, 60 ans, planteur, alcoolique et fumeur connu, souffre d'une tuberculose pulmonaire. Immunocompétent, il est sous votre responsabilité dans le service de médecine au CHR d'Abengourou avec un état d'hygiène lamentable.\",\n       \"text\": \"Quels sont parmi les propositions suivantes, les trois facteurs favorisant l'évolution de la maladie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La puberté\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le SIDA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'IDR négative\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'obésité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La sous-alimentation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le SIDA ; C. L'IDR négative ; E. La sous-alimentation\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le SIDA (infection à VIH), la sous-alimentation (malnutrition) et une IDR négative (absence de réponse immunitaire, déficit de l'immunité cellulaire) favorisent l'évolution vers la tuberculose maladie. La puberté et l'obésité ne figurent pas parmi ces facteurs. Remarque : Dans le sujet, le cas présente M. Kouamé comme « immunocompétent », alors que le SIDA est retenu comme facteur.\\n\\nSource : Tuberculose (diaporama), Facteurs favorisant la maladie ; Cours de sémiologie médicale et pathologies respiratoires, Test tuberculinique (p. 78)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__1\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 : M. KOUAME Oi Kouamé, 60 ans, planteur, alcoolique et fumeur connu, souffre d'une tuberculose pulmonaire. Immunocompétent, il est sous votre responsabilité dans le service de médecine au CHR d'Abengourou avec un état d'hygiène lamentable.\",\n       \"text\": \"Parmi les signes cliniques suivants de la tuberculose pulmonaire, cocher les deux qui sont des signes généraux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dyspnée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Amaigrissement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Expectoration\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Asthénie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Amaigrissement ; E. Asthénie\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Les signes généraux (d'imprégnation tuberculeuse) sont l'asthénie, l'anorexie, l'amaigrissement, la fièvre vespérale et les sueurs nocturnes. La toux, l'expectoration et la dyspnée sont des signes respiratoires.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, Tuberculose pulmonaire – signes évocateurs (p. 74) ; Tuberculose (diaporama), Diagnostic positif\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__2\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 : M. KOUAME Oi Kouamé, 60 ans, planteur, alcoolique et fumeur connu, souffre d'une tuberculose pulmonaire. Immunocompétent, il est sous votre responsabilité dans le service de médecine au CHR d'Abengourou avec un état d'hygiène lamentable.\",\n       \"text\": \"Parmi les propositions ci-dessous, une (1) fait partie des rôles de l'IDE dans la prise en charge d'un tuberculeux. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Interpréter les résultats des examens\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner le malade\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mettre le malade à jeun avant le prélèvement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Poser le diagnostic\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Mettre le malade à jeun avant le prélèvement\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le rôle propre de l'IDE dans le diagnostic bactériologique est le recueil des crachats : mettre le malade à jeun avant le prélèvement, utiliser un crachoir stérile, s'assurer qu'il s'agit bien de crachats. Interpréter, examiner et poser le diagnostic relèvent du médecin.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, Rôle de l'infirmier dans le diagnostic bactériologique (p. 75) ; Cours Médecine IDE 2 INFAS (actualisé 2020) (p. 57)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__3\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 : M. KOUAME Oi Kouamé, 60 ans, planteur, alcoolique et fumeur connu, souffre d'une tuberculose pulmonaire. Immunocompétent, il est sous votre responsabilité dans le service de médecine au CHR d'Abengourou avec un état d'hygiène lamentable.\",\n       \"text\": \"Quelles sont les consignes à donner au malade avant qu'il ne débute son traitement antituberculeux ? Cocher les trois bonnes réponses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le traitement impose au moins six (06) repas quotidiens\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les médicaments seront pris après les repas\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les médicaments seront pris devant témoin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le respect des doses est impérieux\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le traitement dure au moins six mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Les médicaments seront pris devant témoin ; D. Le respect des doses est impérieux ; E. Le traitement dure au moins six mois\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Règles du traitement : prise devant témoin (traitement supervisé), respect strict des doses prescrites, prise régulière, et durée d'au moins six mois. Les médicaments se prennent en prise unique le matin à jeun, pas après les repas.\\n\\nSource : Tuberculose (diaporama), Règles du traitement antituberculeux ; Cours de sémiologie médicale et pathologies respiratoires, Règle du traitement (p. 75)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__4\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 : M. KOUAME Oi Kouamé, 60 ans, planteur, alcoolique et fumeur connu, souffre d'une tuberculose pulmonaire. Immunocompétent, il est sous votre responsabilité dans le service de médecine au CHR d'Abengourou avec un état d'hygiène lamentable.\",\n       \"text\": \"En vous référant au texte, quel est le besoin prioritaire de M. KOULAHI Loué ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Manger et boire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Eliminer\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"S'occuper en vue de se réaliser\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Être propre, soigné et protéger ses téguments\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Être propre, soigné et protéger ses téguments\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le texte insiste sur un « état d'hygiène lamentable » : le besoin d'être propre, soigné et de protéger ses téguments est le besoin prioritaire. Remarque : Dans le sujet, le patient du cas s'appelle M. KOUAME, mais la question parle de « M. KOULAHI Loué ».\\n\\nSource : Modèle de V. Henderson (explication en partie hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__5\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins palliatifs consistent à procurer un mieux-être aux malades dans l'une des situations suivantes, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Malade amaigri\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Devant des vomissements en jet\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Phase terminale de la maladie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Malade refusant de s'alimenter\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Phase terminale de la maladie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les soins palliatifs s'adressent aux personnes atteintes d'une maladie grave, évolutive, à un stade avancé ou terminal ; ils visent le confort et la meilleure qualité de vie possible jusqu'au décès.\\n\\nSource : Gériatrie PP L2, chap. II Soins palliatifs ; Soins palliatifs, Module 2, chap. I (p. 19)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__6\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants deux sont des risques et complications de la pose de la sonde urinaire ; lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rétention d'urine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Infections\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insuffisance rénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Perforation de l'urètre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le gonflement du ballonnet dans l'urètre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Infections ; D. Perforation de l'urètre\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La pose d'une sonde urinaire expose surtout à l'infection urinaire (le cathétérisme est un facteur favorisant) et au traumatisme de l'urètre (fausse route, perforation), notamment si le ballonnet est gonflé dans l'urètre. Remarque : Le « gonflement du ballonnet dans l'urètre » est une cause de traumatisme plutôt qu'une complication en soi.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Infections des voies urinaires (p. 160) ; complément hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__7\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le réservoir de germe de la fièvre typhoïde est : cocher la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La chauve-souris\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'anophèle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La glossine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le singe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'homme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. L'homme\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Les salmonelles responsables de la fièvre typhoïde ont l'homme (malade ou porteur chronique) pour seul réservoir ; la transmission est féco-orale (mains sales, eau, aliments). L'anophèle et la glossine sont des vecteurs d'autres maladies.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde (porteurs chroniques, coproculture) ; réservoir : explication en partie hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__8\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes cliniques suivants trois sont compatibles avec un accès palustre de primo-invasion non compliqué. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Raideur méningée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Photophobie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vomissement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Céphalées ; C. Fièvre ; E. Vomissement\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'accès palustre simple associe fièvre, céphalées et troubles digestifs (vomissements, nausées). La raideur méningée et la photophobie orientent vers une méningite.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – 4-1 Paludisme simple (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__9\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces facteurs de risque, deux compliquent la maladie à coronavirus :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La furonculose\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La dermatose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le diabète sucré\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'HTA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Le diabète sucré ; D. L'HTA\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le diabète et l'HTA (avec cardiopathies, obésité, insuffisance rénale…) sont des facteurs de risque de forme grave de COVID-19.\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19 – facteurs de risque\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__10\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mode de transmission le plus fréquent du VIH :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Transmission par le sang et dérivés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Transmission sexuelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Transmission materno-fœtale (mère-enfant)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Transmission sexuelle\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La voie sexuelle est le mode de transmission le plus courant du VIH.\\n\\nSource : Documents de révision L3 Médecine, VIH, QCD 34 (p. 66)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__11\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs suivants, lesquels sont à la base de la survenue des maladies chroniques non transmissibles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prise de poids\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cultivateur de profession\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tabagisme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sédentarité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Repos insuffisant\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Régime végétarien\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Prise de poids ; C. Tabagisme ; D. Sédentarité ; E. Repos insuffisant\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La prise de poids (obésité), le tabagisme et la sédentarité sont des facteurs de risque reconnus des maladies non transmissibles (HTA, diabète…). Remarque : Le « repos insuffisant » est coché par la correction nationale mais n'apparaît pas dans les listes de facteurs de risque des cours.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), HTA – causes ou facteurs de risque (p. 63-64) ; Documents de révision L3 Médecine, MNT, QCM 4\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__12\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi la liste des maladies suivantes, deux sont virales, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rougeole\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Grippe\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diphtérie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Choléra\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Rougeole ; C. Grippe\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La rougeole et la grippe sont des maladies virales. La fièvre typhoïde, la diphtérie et le choléra sont bactériens.\\n\\nSource : Documents de révision L3 Médecine, Rougeole, QCD 8 ; Cours de sémiologie médicale et pathologies respiratoires, OAP – causes infectieuses (grippe, rougeole)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__13\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions ci-après, choisissez la position idéale d'un patient au cours d'une crise d'OAP (Œdème Aigu du Poumon).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Position latérale jambe légèrement repliée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Position dorsale jambe tendue\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Position assise jambe pendante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Position assise jambe pendante\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pendant l'OAP, le patient est installé en position demi-assise, jambes pendantes, ce qui limite le retour veineux et soulage la dyspnée.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Traitement de l'OAP – rôle de l'infirmier (p. 84)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__14\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Choisissez l'installation convenable pour les personnes présentant des difficultés cardio-respiratoires.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Installation Dorsale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Installation Latérale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Installation Assise\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Installation Assise\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le patient en difficulté cardio-respiratoire est installé en position assise (ou demi-assise), qui facilite la respiration.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), CAT devant une IVG (p. 88) ; OAP (p. 84)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__15\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Choisissez deux signes d'insuffisance ventriculaire droite dans cette liste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Oligurie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Œdèmes des membres inférieurs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dyspepsie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Oligurie ; B. Œdèmes des membres inférieurs\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"L'insuffisance ventriculaire droite donne des signes d'hypertension veineuse : œdèmes des membres inférieurs, hépatomégalie, turgescence jugulaire, reflux hépato-jugulaire, oligurie. Remarque : Le cours cite aussi la dyspepsie et les vomissements parmi les troubles digestifs accompagnant les hépatalgies de l'IVD.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Insuffisance ventriculaire droite – signes cliniques (p. 88)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__16\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Choisissez deux objectifs des soins palliatifs parmi les propositions suivantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Soulager la souffrance des proches du malade liée à la maladie.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prescrire des thérapies pour guérir le malade.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Soulager la douleur du malade sans agir sur la cause de la maladie.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Administrer des médicaments au malade pour agir sur la cause de la maladie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Soulager la souffrance des proches du malade liée à la maladie. ; C. Soulager la douleur du malade sans agir sur la cause de la maladie.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les soins palliatifs visent à soulager la douleur et les symptômes sans chercher à guérir la cause, et à soutenir les proches. Prescrire une thérapie pour guérir ou agir sur la cause ne fait pas partie de leurs objectifs.\\n\\nSource : Gériatrie PP L2, chap. II Soins palliatifs (diapo 19) ; Documents de révision L3 Médecine, Soins palliatifs, QCD 26\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__17\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez parmi ces examens biologiques celui qui met en évidence les anticorps anti-plasmodium falciparum.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"NFS\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"GOUTTE EPAISSE\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"TDR\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Frottis sanguin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. TDR\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient le TDR.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – VI Diagnostic biologique (p. 51)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__18\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"L'étudiant de licence 2 qui est de garde avec vous se référant au modèle conceptuel de Virginia Henderson a relevé les besoins ci-dessous. Indiquer les deux qui sont prioritaires ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Être propre, soigné et protéger ses téguments et phanères\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Se mouvoir et se maintenir en bonne posture\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Eviter les dangers\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"S'occuper en vue de se réaliser\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Être propre, soigné et protéger ses téguments et phanères ; B. Se mouvoir et se maintenir en bonne posture\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"M. Kodjo n'a reçu aucun soin d'hygiène depuis deux jours (besoin d'être propre et de protéger ses téguments) et présente des contractures (raideur de la nuque, trismus) qui gênent ses mouvements (besoin de se mouvoir et de garder une bonne posture).\\n\\nSource : Modèle de V. Henderson (explication en partie hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__19\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"Le diagnostic du médecin révèle que M. KODJO souffre de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paludisme grave\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tétanos\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méningite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diphtérie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Tétanos\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le trismus (contracture des muscles masticateurs) est le signe d'invasion du tétanos ; avec la raideur, il oriente vers le tétanos. Remarque : Le cours précise que le trismus ne s'accompagne pas de fièvre ; dans le sujet, la fièvre et la raideur de nuque pouvaient aussi évoquer une méningite.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Tétanos – Étude clinique (invasion, phase d'état)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__20\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"Quel est l'indice de masse corporelle de M. KODJO ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"20\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"24\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"28\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"30\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 24\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"IMC = poids / taille² = 60 / (1,58)² = 60 / 2,496 ≈ 24. (explication hors cours du projet : calcul)\\n\\nSource : Calcul de l'IMC\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__21\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"En outre, le médecin prescrit du valium injectable à M. KODJO à la posologie de 0.5 mg/kg dans du sérum glucosé 250 cc en perfusion pendant 4 heures. Combien d'ampoules devez-vous mettre dans la perfusion de M. KODJO sachant qu'une ampoule est dosée à 10mg/2ml ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1amp\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1.5amp\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2amp\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3amp\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 3amp\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dose = 0,5 mg/kg × 60 kg = 30 mg. Une ampoule = 10 mg, donc 30 ÷ 10 = 3 ampoules. (explication hors cours du projet : calcul)\\n\\nSource : Calcul de dose\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__22\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"Quelle est la DCI du valium ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prazépam\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Diazépam\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lorazépam\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bromazépam\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Diazépam\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La DCI du Valium® est le diazépam. Le lorazépam est le Temesta®, le bromazépam le Lexomil®, le prazépam le Lysanxia®.\\n\\nSource : Neuro-psychiatrie, « Quelques médicaments » (tableau des benzodiazépines, p. 46)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__23\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique N° 2 : Vous êtes de garde au service de médecine au CHR d'Abengourou en qualité d'Infirmier Diplômé d'Etat. Vous recevez Monsieur KODJO Paulin, cultivateur âgé de 47 ans. Il présente une raideur de la nuque, un trismus, une fièvre. Depuis son entrée à l'hôpital il y a deux jours, il n'a reçu aucun soin d'hygiène et de confort. Monsieur KODJO pèse 60 kilogrammes avec une taille de 1,58 mètres.\",\n       \"text\": \"Quel sera le débit de cette perfusion ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"19 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"21 gouttes/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"22 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 21 gouttes/min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (ml) × 20 / durée (min) = 250 × 20 / 240 ≈ 20,8, soit 21 gouttes/min. (explication hors cours du projet : calcul)\\n\\nSource : Formule du débit de perfusion (1 ml = 20 gouttes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__24\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre jaune est une zoonose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fièvre jaune est une zoonose : le virus circule naturellement entre les singes et les moustiques (cycle forestier) et l'homme est contaminé accidentellement.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre jaune – réservoir et transmission\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__25\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'esprit de groupe est l'un des déterminants de la propagation favorisant l'expansion de l'infection à VIH chez les jeunes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez les jeunes, l'effet de groupe (pression des pairs, comportements à risque partagés) est un déterminant de la propagation du VIH.\\n\\nSource : Documents de révision L3 Médecine, VIH, QCD 24 (déterminants de la propagation) ; complément hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__26\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La transmission de la maladie à COVID-19 se fait toujours par voie directe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La transmission de la COVID-19 est directe (gouttelettes, contact) et indirecte (surfaces et objets contaminés) : elle ne se fait pas « toujours » par voie directe.\\n\\nSource : Documents de révision L3 Médecine, COVID-19, QCD 2 et 4 (p. 62)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__27\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'incubation de l'infection à COVID-19 dure en moyenne 15 jours.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19 – rôle de l'IDE (contage dans les 10 ou 14 jours) ; Documents de révision L3 Médecine, COVID-19, QCD 3\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__28\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dysosmie et la dysgueusie constituent des signes pathognomoniques de la maladie à COVID-19.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19 – rôle de l'IDE (signes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__29\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La stigmatisation et le refus de l'isolement strict pour quelques jours sont des causes de la propagation de la maladie à COVID-19.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'isolement strict est la règle pour un patient COVID-19 ; le refus de l'isolement et la stigmatisation (qui pousse à cacher la maladie) favorisent la propagation.\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19 – CAT auprès d'un patient (isolement strict)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__30\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le dépistage de la femme enceinte sans son conjoint permet de réduire le risque de transmission de l'infection à VIH.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le dépistage de la femme enceinte seule ne suffit pas : le dépistage du conjoint (dépistage du couple) est nécessaire pour prévenir la transmission, notamment si le conjoint s'infecte pendant la grossesse ou l'allaitement.\\n\\nSource : Explication en partie hors cours du projet (PTME, dépistage du couple)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__31\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rougeole est une maladie immunisante.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La rougeole est une maladie immunisante : une rougeole guérie protège à vie. Le document de révision propose l'affirmation inverse (« non immunisante ») comme fausse.\\n\\nSource : Documents de révision L3 Médecine, Rougeole, QCD 5 (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__32\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La transmission de la maladie à COVID-19 se fait toujours par voie directe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même affirmation que la question 31 (doublon dans le sujet) : la transmission de la COVID-19 est directe et indirecte.\\n\\nSource : Documents de révision L3 Médecine, COVID-19, QCD 2 et 4 (p. 62)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__33\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic biologique de certitude de la fièvre typhoïde est basé uniquement sur l'hémoculture et/ou la coproculture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'examen de certitude de la fièvre typhoïde est l'hémoculture ; la coproculture aide en période de diarrhée et pour dépister le portage. Le sérodiagnostic de Widal ne permet pas un diagnostic de certitude.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – Examen de certitude (p. 64)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__34\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La diastole correspond au repos du cœur. C'est à cette période que les deux ventricules se remplissent de sang venant des oreillettes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ».\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), HTA – composition de la pression artérielle (p. 64-65)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__35\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La combinaison ABC + 3TC + DTG est l'option préférentielle de traitement ARV chez une personne dépistée VIH positive et insuffisance rénale chronique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En cas de trouble de la fonction rénale, on remplace le TDF (néphrotoxique) par l'ABC : le schéma devient ABC + 3TC + DTG.\\n\\nSource : Cours VIH Licence 2 (diaporama), diapos 81-82 (contre-indications du TDF ; patient avec comorbidité)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__36\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le glomérule est une sorte de chambre de filtration du plasma.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le glomérule est l'unité de filtration du rein : le plasma y est filtré pour former l'urine primitive (débit de filtration glomérulaire).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Insuffisance rénale chronique (filtration glomérulaire) ; complément hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__37\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les douleurs abdominales, les nausées et vomissements peuvent être des signes d'appel d'une insuffisance rénale chronique (IRC).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'IRC se manifeste notamment par des symptômes gastro-intestinaux (anorexie, nausées, vomissements, diarrhées), avec fatigue, céphalées et confusion.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Insuffisance rénale chronique – III Manifestations cliniques (p. 172)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__38\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En raison de la gravité de la co-infection, tout malade dépisté tuberculeux de nos jours doit faire obligatoirement l'objet d'un counseling en vue du test de dépistage VIH, même sans son consentement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Tuberculose et VIH sont étroitement liés : la recherche de l'infection à VIH est systématique chez tout tuberculeux, d'où le counseling. Remarque : Le dépistage du VIH reste en principe soumis au consentement ; « même sans son consentement » est discutable, même si le cours insiste sur le caractère systématique.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Tuberculose – conclusion (p. 58) ; Tuberculose (diaporama), classification selon le statut VIH\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__39\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Se laver régulièrement les mains avec de l'eau et du savon contribue efficacement à la prévention de la tuberculose nosocomiale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La tuberculose se transmet par voie aérienne : la prévention en milieu de soins repose sur l'isolement des patients bacillifères, l'aération des chambres et le port de masques. Le lavage des mains n'est pas la mesure efficace contre cette transmission.\\n\\nSource : Tuberculose (diaporama), Prévention de la transmission en milieu de soins\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__40\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pollakiurie est l'augmentation du volume des urines pendant la nuit.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La pollakiurie est l'augmentation de la fréquence des mictions (de jour et/ou de nuit) ; l'augmentation du volume des urines la nuit s'appelle la nycturie. (explication hors cours du projet)\\n\\nSource : Cours sur les adénomes de la prostate (pollakiurie nocturne et/ou diurne) ; définition hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__41\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'insuffisance cardiaque se définit par l'état de défaillance circulatoire qui résulte de l'impossibilité pour le cœur d'assurer un débit sanguin suffisant au besoin de l'organisme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'insuffisance cardiaque est l'incapacité du cœur à assurer un débit sanguin suffisant aux besoins de l'organisme (d'abord à l'effort, puis au repos).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), IVG – définition (p. 85)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__42\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il n'y a pas d'ulcère gastro-duodénal sans la bactérie Helicobacter pylori.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Ulcère gastro-duodénal – UGD non liés à H. pylori, AINS, syndrome de Zollinger-Ellison (p. 115-116)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__43\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de KOPLICK se rencontre dans la rougeole. Il se définit comme une éruption sur la joue de petits points blancs.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le signe de Köplick est spécifique de la rougeole : petites taches blanchâtres sur la face interne des joues, avant l'éruption.\\n\\nSource : Documents de révision L3 Médecine, Rougeole, QCD 7 (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__44\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anophèle femelle est l'agent pathogène du paludisme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme (cycle du Plasmodium) ; Documents de révision L3 Médecine, paludisme, QCD 3-4\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__45\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cirrhose est une pathologie de la rate en réponse à des agressions de natures variées, caractérisées par un bouleversement de l'architecture splénique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La cirrhose est une maladie du foie (et non de la rate), caractérisée par un bouleversement de l'architecture hépatique (fibrose et nodules de régénération).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Cirrhose – I Définition (p. 127-128)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__46\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La vomique est une forme d'expectoration caractérisée par le rejet brutal et massif d'une grande quantité de pus ou de liquide clair à la faveur d'un effort de toux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La vomique est le rejet brutal par la bouche d'une collection abondante de pus ou de sérosité provenant d'une cavité thoracique qui s'ouvre dans une bronche.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, La vomique – définition (p. 6)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__47\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'odynophagie correspond à une douleur ressentie lors de la déglutition.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'odynophagie est une douleur ressentie lors de la déglutition.\\n\\nSource : Cours d'hépato-gastro-entérologie, Œsophagites – manifestations cliniques (p. 4-5)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__48\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cholécystite aiguë est le plus souvent liée à l'obstruction du canal cystique par un calcul.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La cholécystite aiguë est une inflammation de la vésicule biliaire, le plus souvent causée par un calcul enclavé dans le canal cystique (90 à 95 % des cas).\\n\\nSource : Cours d'hépato-gastro-entérologie, Chapitre 5 Cholécystite (p. 26-27)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j4-ide__49\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après une endoscopie sous sédation, une somnolence excessive, une hypotension ou une dépression respiratoire doivent être recherchées.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après une endoscopie sous sédation, l'infirmier surveille la conscience, la tension et la respiration : somnolence excessive, hypotension et dépression respiratoire sont des complications de la sédation à rechercher.\\n\\nSource : Cours d'hépato-gastro-entérologie, Chapitre 13 Préparation et surveillance des examens endoscopiques (p. 62-63) ; complément hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
